# === canonical observation-step normalization ===
_STEP_BASE=agent
def agent(observation,configuration=None):
    o=observation
    if isinstance(o,dict) and 'step' not in o:
        o=dict(o);o['step']=int(o.get('day',0) or 0)*24+int(o.get('hour',0) or 0)
    return _STEP_BASE(o,configuration)

# === merge duplicate SELL lots by item, preserving first-item order ===
_SFM_BASE=agent
def agent(observation,configuration=None):
    a=copy.deepcopy(_SFM_BASE(observation,configuration));m=list(a.get('market',[]) or []);order=[];qty={};other=[]
    for x in m:
        if isinstance(x,list) and len(x)>=3 and x[0]=='SELL':
            item=x[1]
            try:q=max(0,int(x[2]))
            except:q=0
            if item not in qty:order.append(item);qty[item]=0
            qty[item]+=q
        else:other.append(x)
    a['market']=([['SELL',k,qty[k]] for k in order if qty[k]>0]+other)[:10];return a

