def opening_q_agent(observation,configuration=None):
    o=observation
    if isinstance(o,dict) and 'step' not in o:
        o=dict(o);o['step']=int(o.get('day',0) or 0)*24+int(o.get('hour',0) or 0)
    a=copy.deepcopy(_OQ_BASE(o,configuration));s=int(o.get('step',0) or 0)
    if s==0:
        m=[x for x in list(a.get('market',[]) or []) if not (isinstance(x,list) and len(x)>=3 and x[0]=='BUY_PRODUCT' and x[1]=='WHEAT')]
        if _OQ_Q0>0:m=[['BUY_PRODUCT','WHEAT',_OQ_Q0]]+m
        a['market']=m[:10]
    elif s==1:
        m=[]
        for x in list(a.get('market',[]) or []):
            if isinstance(x,list) and len(x)>=3 and x[1]=='WHEAT' and x[0] in ('BUY_PRODUCT','SELL'):continue
            m.append(x)
        delta=5-_OQ_Q0
        if delta>0:m=[['BUY_PRODUCT','WHEAT',delta]]+m
        elif delta<0:m=[['SELL','WHEAT',-delta]]+m
        a['market']=m[:10]
    return a
