# === Capital-Adaptive Aegis: frozen reproducible controller ===
# Generic public-state adaptation only; no opponent IDs or seed fingerprints.
_CAP_BASE = agent
_CAP_ORIG_KEY = _key
_CAP_MODE = {0: 'NORMAL', 1: 'NORMAL'}
_CAP_OPP_WHEAT_BUY = {0: 0, 1: 0}
_CAP_CURRENT_PLAYER = None


def _cap_key(step, shops):
    """Use only prefix-compatible whole-programme blocks at 72-turn boundaries."""
    player = _CAP_CURRENT_PLAYER
    mode = _CAP_MODE.get(player, 'NORMAL') if player is not None else 'NORMAL'
    if (
        mode == 'MEDIUM_CAPITAL'
        and shops
        and shops[0] in BAL
        and 'YARN_STORE' not in list(shops[:2])
    ):
        if 144 <= step < 216:
            return 'S2_MILK', step - 144
        if 216 <= step < 288:
            return 'P3_YARN_THIRD', step - 216
    return _CAP_ORIG_KEY(step, shops)


# `_agent` resolves `_key` dynamically, so the branch above affects complete
# programme blocks without rewriting primitive physical actions.
_key = _cap_key


def capital_adaptive_aegis(observation, configuration=None):
    global _CAP_CURRENT_PLAYER
    o = observation
    if isinstance(o, dict) and 'step' not in o:
        o = dict(o)
        o['step'] = int(o.get('day', 0) or 0) * 24 + int(o.get('hour', 0) or 0)
    player = int(o.get('player', 0) or 0)
    step = int(o.get('step', 0) or 0)

    if step == 0:
        _CAP_MODE[player] = 'NORMAL'
        _CAP_OPP_WHEAT_BUY[player] = 0
    elif step == 1:
        inv = int((((o.get('market', {}) or {}).get('inventory', {}) or {}).get('WHEAT', 10000)) or 10000)
        # With our q0=3 opening and one unit of town consumption, 9996 is the
        # public no-opponent-buy reference inventory at step 1.
        opp_buy = max(0, 9996 - inv)
        _CAP_OPP_WHEAT_BUY[player] = opp_buy
        if 11 <= opp_buy <= 18:
            _CAP_MODE[player] = 'MEDIUM_CAPITAL'
        elif opp_buy >= 20:
            _CAP_MODE[player] = 'WHEAT_SHOCK'
        else:
            _CAP_MODE[player] = 'NORMAL'

    _CAP_CURRENT_PLAYER = player
    try:
        a = copy.deepcopy(_CAP_BASE(o, configuration))
    finally:
        _CAP_CURRENT_PLAYER = None

    # Public-market shock arbitrage.  This replaces only the step-1 Wheat
    # top-up; it never touches worker choreography or later programme inputs.
    if step == 1 and _CAP_MODE.get(player) == 'WHEAT_SHOCK':
        opp_buy = int(_CAP_OPP_WHEAT_BUY.get(player, 0) or 0)
        sell_qty = 1 if opp_buy >= 45 else 3
        market = []
        for x in list(a.get('market', []) or []):
            if isinstance(x, list) and len(x) >= 2 and x[1] == 'WHEAT' and x[0] in ('BUY_PRODUCT', 'SELL'):
                continue
            market.append(x)
        a['market'] = ([['SELL', 'WHEAT', sell_qty]] + market)[:10]
    return a

agent = capital_adaptive_aegis


