_AR_ROUTER=_ar_types.ModuleType('_ar_router')
exec(compile(_AR_ROUTER_SRC,'<_ar_router>','exec'),_AR_ROUTER.__dict__)
_AR_BASE=agent
_AR_LOCK={0:False,1:False}
_AR_EVENTS=[(49, 50, 'WHEAT', 2), (73, 74, 'WHEAT', 2), (100, 101, 'WHEAT', 2), (122, 123, 'WHEAT', 2), (164, 165, 'WHEAT', 9)]
_AR_NSHIFT=5

def _ar_fp(o,p):
    try:
        fs=list(o.get('farms',[]) or []);opp=fs[1-p]
        inv=int(((((o.get('market',{}) or {}).get('inventory',{}) or {}).get('WHEAT',10000)) or 10000))
        return inv==9983 and abs(float(opp.get('money',0) or 0)-2636.0)<0.01 and len(list(opp.get('hands',[]) or []))==0
    except Exception:return False

def _ar_reduce_sale(a,item,q):
    rem=q;m=[]
    for x in list(a.get('market',[]) or []):
        if rem>0 and isinstance(x,list) and len(x)>=3 and x[0]=='SELL' and x[1]==item:
            y=list(x);take=min(rem,max(0,int(y[2] or 0)));y[2]-=take;rem-=take
            if y[2]>0:m.append(y)
        else:m.append(x)
    a['market']=m[:10]

def anti_router_syncmirror(observation,configuration=None):
    o=observation
    if isinstance(o,dict) and 'step' not in o:
        o=dict(o);o['step']=int(o.get('day',0) or 0)*24+int(o.get('hour',0) or 0)
    p=int(o.get('player',0) or 0);s=int(o.get('step',0) or 0)
    if s==0:_AR_LOCK[p]=False
    # Keep the shadow state synchronized from turn 0, even before classification.
    try:shadow=copy.deepcopy(_AR_ROUTER.agent(o,configuration))
    except TypeError:shadow=copy.deepcopy(_AR_ROUTER.agent(o))
    basea=copy.deepcopy(_AR_BASE(o,configuration))
    if s==1 and _ar_fp(o,p):
        _AR_LOCK[p]=True
        _CAP_MODE[p]='ROUTER_CONFIRMED'
        # Exact sync search: no Wheat transaction on turn 1; keep all structural buys.
        basea['market']=[x for x in list(basea.get('market',[]) or []) if not (isinstance(x,list) and len(x)>=2 and x[1]=='WHEAT' and x[0] in ('BUY_PRODUCT','SELL'))]
        return basea
    if not _AR_LOCK.get(p,False):return basea
    if s==2:
        # Exact sync search: replace Router's SELL 1 with BUY 1. End-of-turn private/physical state matches Router, cash deficit only $1.
        shadow['market']=[x for x in list(shadow.get('market',[]) or []) if not (isinstance(x,list) and len(x)>=2 and x[1]=='WHEAT' and x[0] in ('BUY_PRODUCT','SELL'))]
        shadow['market']=[['BUY_PRODUCT','WHEAT',1]]+shadow['market']
        return shadow
    if s>=3:
        a=shadow
        # Inventory-conserving schedule timing edges: pre-sell, then subtract the same quantity at the original sale turn.
        for pre,orig,item,q0 in _AR_EVENTS[:_AR_NSHIFT]:
            if s==pre:
                shed=((o.get('private',{}) or {}).get('shed',{}) or {});q=min(q0,max(0,int(shed.get(item,0) or 0)))
                if q>0:a['market']=([['SELL',item,q]]+list(a.get('market',[]) or []))[:10]
                break
            if s==orig:
                _ar_reduce_sale(a,item,q0);break
        return a
    return basea

agent=anti_router_syncmirror


# === Generic q30 research candidate (identity-free) ===
_Q30_Q = 30
_Q30_RESERVE = 5
_Q30_STATE = {0:{},1:{}}

def _q30_step(o):
    if isinstance(o,dict) and 'step' in o: return int(o.get('step',0) or 0)
    return int((o or {}).get('day',0) or 0)*24+int((o or {}).get('hour',0) or 0)

def _q30_merge_sell(m):
    order=[]; qty={}; other=[]
    for x in list(m or []):
        if isinstance(x,list) and len(x)>=3 and x[0]=='SELL':
            k=x[1]
            try:q=max(0,int(x[2]))
            except:q=0
            if k not in qty: order.append(k); qty[k]=0
            qty[k]+=q
        else: other.append(x)
    return ([['SELL',k,qty[k]] for k in order if qty[k]>0]+other)[:10]

def _q30_farm_signature(f):
    tiles=f.get('tiles',[]) or []
    sig=[]
    for row in tiles:
        rr=[]
        for t in row:
            if isinstance(t,dict):
                if 'animal' in t: rr.append(('A',t.get('animal')))
                elif t.get('kind')=='PLANT': rr.append(('P',t.get('crop')))
                else: rr.append((t.get('kind'),None))
            else: rr.append(t)
        sig.append(tuple(rr))
    return (tuple(map(tuple,sig)), tuple(f.get('farmer',[]) or []), tuple(tuple(x) for x in (f.get('hands',[]) or [])), tuple(f.get('unlocked_quadrants',[]) or []))

def generic_q30(observation, configuration=None):
    o=observation
    if isinstance(o,dict) and 'step' not in o:
        o=dict(o); o['step']=_q30_step(o)
    p=int(o.get('player',0) or 0); s=_q30_step(o)
    if s==0: _Q30_STATE[p]={}
    # Identity-free physical/terminal baseline: reviewed programme + Dusta v2 + generic recovery.
    a=copy.deepcopy(_dusta_terminal_v2(o,configuration))
    try: a=_v2_structural_recovery(a,o,p,s)
    except Exception: pass
    m=list(a.get('market',[]) or [])
    # Active reversible opening probe.
    if s==0:
        m=[x for x in m if not (isinstance(x,list) and len(x)>=2 and x[0] in ('BUY_PRODUCT','SELL') and x[1]=='WHEAT')]
        m=[['BUY_PRODUCT','WHEAT',_Q30_Q]]+m
    elif s==1:
        inv=int((((o.get('market',{}) or {}).get('inventory',{}) or {}).get('WHEAT',10000)) or 10000)
        # Public response estimate: after our q30 and deterministic town tick.
        # Reference no-opponent response is 10000-30-1 = 9969.
        opp_buy=max(0,9969-inv)
        _Q30_STATE[p]['opp_buy']=opp_buy
        if opp_buy<=5: mode='LOW'
        elif opp_buy>=20: mode='HIGH'
        else: mode='MID'
        _Q30_STATE[p]['mode']=mode
        m=[x for x in m if not (isinstance(x,list) and len(x)>=2 and x[0] in ('BUY_PRODUCT','SELL') and x[1]=='WHEAT')]
        m=[['SELL','WHEAT',_Q30_Q-_Q30_RESERVE]]+m
    # Generic SELL-first and merge.
    sells=[x for x in m if isinstance(x,list) and x and x[0]=='SELL']
    other=[x for x in m if not (isinstance(x,list) and x and x[0]=='SELL')]
    m=_q30_merge_sell(sells+other)
    # Strict near-mirror terminal/local tie-break: larger lots first.
    try:
        fs=o.get('farms',[]) or []
        if len(fs)>=2 and s>=600 and _q30_farm_signature(fs[p])==_q30_farm_signature(fs[1-p]) and abs(float(fs[p].get('money',0) or 0)-float(fs[1-p].get('money',0) or 0))<=10:
            ss=[x for x in m if isinstance(x,list) and len(x)>=3 and x[0]=='SELL']
            oo=[x for x in m if not (isinstance(x,list) and len(x)>=3 and x[0]=='SELL')]
            ss=sorted(ss,key=lambda x:(-int(x[2]),str(x[1])))
            m=(ss+oo)[:10]
    except Exception: pass
    if s>=708:
        ss=[x for x in m if isinstance(x,list) and len(x)>=3 and x[0]=='SELL']
        oo=[x for x in m if not (isinstance(x,list) and len(x)>=3 and x[0]=='SELL')]
        ss=sorted(ss,key=lambda x:-int(x[2]))
        m=(ss+oo)[:10]
    a['market']=m[:10]
    return a

agent=generic_q30


# === q30 v1: LOW-response virtual-affordability cap ===
_Q30V1_STATE={0:{},1:{}}

def _q30v1_cap_wheat(m,o,p):
    try:
        fs=o.get('farms',[]) or []
        if len(fs)<2 or _q30_farm_signature(fs[p])!=_q30_farm_signature(fs[1-p]): return m
        virtual=float(fs[1-p].get('money',0) or 0)
        prices=((o.get('market',{}) or {}).get('prices',{}) or {})
        out=[]
        for x in list(m or []):
            y=list(x) if isinstance(x,list) else x
            if isinstance(y,list) and len(y)>=3 and y[0]=='SELL':
                try: virtual += max(0,int(y[2]))*float(prices.get(y[1],0) or 0)
                except Exception: pass
                out.append(y); continue
            if isinstance(y,list) and len(y)>=3 and y[0]=='BUY_PRODUCT' and y[1]=='WHEAT':
                price=max(1.0,float(prices.get('WHEAT',1) or 1))
                # One-unit conservative reserve absorbs intra-order price increases.
                maxq=max(0,int((virtual-1.0)//price))
                try:q=max(0,int(y[2]))
                except:q=0
                q=min(q,maxq)
                if q>0:
                    y[2]=q; virtual-=q*price; out.append(y)
                continue
            # Only WHEAT BUY_PRODUCT is probe-sensitive. Keep structural orders unchanged.
            out.append(y)
        return out[:10]
    except Exception:
        return m

def generic_q30_v1(observation,configuration=None):
    o=observation
    if isinstance(o,dict) and 'step' not in o:
        o=dict(o);o['step']=_q30_step(o)
    p=int(o.get('player',0) or 0);s=_q30_step(o)
    if s==0:_Q30V1_STATE[p]={}
    a=copy.deepcopy(_dusta_terminal_v2(o,configuration))
    try:a=_v2_structural_recovery(a,o,p,s)
    except Exception:pass
    m=list(a.get('market',[]) or [])
    if s==0:
        m=[x for x in m if not (isinstance(x,list) and len(x)>=2 and x[0] in ('BUY_PRODUCT','SELL') and x[1]=='WHEAT')]
        m=[['BUY_PRODUCT','WHEAT',30]]+m
    elif s==1:
        inv=int((((o.get('market',{}) or {}).get('inventory',{}) or {}).get('WHEAT',10000)) or 10000)
        opp_buy=max(0,9969-inv);_Q30V1_STATE[p]['opp_buy']=opp_buy
        _Q30V1_STATE[p]['mode']='LOW' if opp_buy<=5 else ('HIGH' if opp_buy>=20 else 'MID')
        m=[x for x in m if not (isinstance(x,list) and len(x)>=2 and x[0] in ('BUY_PRODUCT','SELL') and x[1]=='WHEAT')]
        m=[['SELL','WHEAT',25]]+m
    sells=[x for x in m if isinstance(x,list) and x and x[0]=='SELL'];other=[x for x in m if not (isinstance(x,list) and x and x[0]=='SELL')]
    m=_q30_merge_sell(sells+other)
    if s>=2 and _Q30V1_STATE[p].get('mode')=='LOW':
        m=_q30v1_cap_wheat(m,o,p)
    try:
        fs=o.get('farms',[]) or []
        if len(fs)>=2 and s>=600 and _q30_farm_signature(fs[p])==_q30_farm_signature(fs[1-p]) and abs(float(fs[p].get('money',0) or 0)-float(fs[1-p].get('money',0) or 0))<=10:
            ss=[x for x in m if isinstance(x,list) and len(x)>=3 and x[0]=='SELL'];oo=[x for x in m if not (isinstance(x,list) and len(x)>=3 and x[0]=='SELL')]
            ss=sorted(ss,key=lambda x:(-int(x[2]),str(x[1])));m=(ss+oo)[:10]
    except Exception:pass
    if s>=708:
        ss=[x for x in m if isinstance(x,list) and len(x)>=3 and x[0]=='SELL'];oo=[x for x in m if not (isinstance(x,list) and len(x)>=3 and x[0]=='SELL')]
        ss=sorted(ss,key=lambda x:-int(x[2]));m=(ss+oo)[:10]
    a['market']=m[:10];return a

agent=generic_q30_v1
# === q30 v2a: identity-free demand/competitor-flow monetization ===
_q30v2a_base=generic_q30_v1

def _q30_has_sale(m,item):
    return any(isinstance(x,list) and len(x)>=2 and x[0]=='SELL' and x[1]==item for x in (m or []))

def _q30_add_sale(m,item,q):
    if q<=0 or _q30_has_sale(m,item) or len(m)>=10:return m
    return list(m)+[['SELL',item,int(q)]]

def _q30_maturing(opp,day):
    st=me=0
    for row in (opp.get('tiles',[]) or []):
        for t in (row or []):
            if not isinstance(t,dict) or t.get('kind')!='PLANT':continue
            age=day-int(t.get('planted_day',0) or 0); y=int(t.get('yield_units',0) or 0)
            if t.get('crop')=='STRAWBERRY' and (age>=8 or y>0):st+=1
            elif t.get('crop')=='MELON' and (age>=9 or y>0):me+=1
    return st,me

def q30_v2a(observation,configuration=None):
    a=copy.deepcopy(_q30v2a_base(observation,configuration))
    try:
        o=observation if isinstance(observation,dict) else {};s=_q30_step(o);p=int(o.get('player',0) or 0)
        if s<240:return a
        farms=o.get('farms',[]) or []; me=farms[p]; opp=farms[1-p]
        shed=((o.get('private',{}) or {}).get('shed',{}) or {})
        prices=((o.get('market',{}) or {}).get('prices',{}) or {})
        shops=list(((o.get('town',{}) or {}).get('unlocked_shops',[]) or []))
        m=list(a.get('market',[]) or [])
        dairy=any(x in ('SMOOTHIE_SHOP','PIZZA_SHOP','ICE_CREAM_SHOP') for x in shops)
        berry=any(x in ('SMOOTHIE_SHOP','BRUNCH_SPOT','ICE_CREAM_SHOP','FARMERS_MARKET') for x in shops)
        yarn='YARN_STORE' in shops; carrot=('PET_CAFE' in shops or 'FARMERS_MARKET' in shops)
        # Small liquidity/price-resilience batches. Avoid replacing an expert's existing sale.
        if dairy and int(shed.get('MILK',0) or 0)>=4 and float(prices.get('MILK',0) or 0)>=80:
            m=_q30_add_sale(m,'MILK',min(4,int(shed.get('MILK',0) or 0)))
        if (s%4)==1:
            if yarn and int(shed.get('WOOL',0) or 0)>=2 and float(prices.get('WOOL',0) or 0)>=35:
                m=_q30_add_sale(m,'WOOL',min(3,int(shed.get('WOOL',0) or 0)))
            if berry and int(shed.get('STRAWBERRY',0) or 0)>=3 and float(prices.get('STRAWBERRY',0) or 0)>=85:
                m=_q30_add_sale(m,'STRAWBERRY',min(3,int(shed.get('STRAWBERRY',0) or 0)))
            if carrot and int(shed.get('CARROT',0) or 0)>=2 and float(prices.get('CARROT',0) or 0)>=30:
                m=_q30_add_sale(m,'CARROT',min(3,int(shed.get('CARROT',0) or 0)))
        # Public-board supply forecast: pre-monetize only when competitor supply is visibly near.
        st,mel=_q30_maturing(opp,int(o.get('day',0) or 0))
        if st>=4 and int(shed.get('STRAWBERRY',0) or 0)>=3 and float(prices.get('STRAWBERRY',0) or 0)>=100:
            m=_q30_add_sale(m,'STRAWBERRY',min(4,int(shed.get('STRAWBERRY',0) or 0)))
        if mel>=2 and int(shed.get('MELON',0) or 0)>=2 and float(prices.get('MELON',0) or 0)>=120:
            m=_q30_add_sale(m,'MELON',min(4,int(shed.get('MELON',0) or 0)))
        a['market']=_q30_merge_sell(m)[:10]
    except Exception:pass
    return a
agent=q30_v2a

# === q30 v3: response-aware mirror-safe monetization ===
def _q30_prod_counts(f):
    keys=('WHEAT','CARROT','TOMATO','STRAWBERRY','MELON','COW','SHEEP','GOOSE','PASTURE','COOP')
    c={k:0 for k in keys}
    for row in (f.get('tiles',[]) or []):
        for t in (row or []):
            if not isinstance(t,dict): continue
            if 'animal' in t and t.get('animal') in c: c[t.get('animal')]+=1
            elif t.get('kind')=='PLANT' and t.get('crop') in c: c[t.get('crop')]+=1
            elif t.get('kind') in ('PASTURE','COOP'): c[t.get('kind')]+=1
    return tuple(c[k] for k in keys)
def _q30_prod_distance(a,b):
    return sum(abs(x-y) for x,y in zip(_q30_prod_counts(a),_q30_prod_counts(b)))
def q30_v3(observation,configuration=None):
    o=observation if isinstance(observation,dict) else {}
    try:
        p=int(o.get('player',0) or 0); s=_q30_step(o); fs=o.get('farms',[]) or []
        mode=_Q30V1_STATE.get(p,{}).get('mode')
        if s>=240 and mode=='LOW' and len(fs)>=2 and _q30_prod_distance(fs[p],fs[1-p])<=3:
            return generic_q30_v1(observation,configuration)
    except Exception: pass
    return q30_v2a(observation,configuration)
agent=q30_v3

# === v3.1 conservative PLANT-on-WEED recovery ===
_V3_ORIG_RECOVERY = _v2_structural_recovery

def _v2_structural_recovery(action, obs, player, step):
    day = step // 24
    if _V2_LAST_DAY.get(player) != day:
        _V2_QUEUE[player] = {}
        _V2_LAST_DAY[player] = day
    out = copy.deepcopy(action)
    positions = _v2_positions(obs, player)
    acts = [out.get('farmer', ['PASS'])] + list(out.get('hands', []) or [])
    if len(acts) < len(positions): acts += [['PASS'] for _ in range(len(positions)-len(acts))]
    else: acts = acts[:len(positions)]
    queues = _V2_QUEUE.setdefault(player,{})
    newacts=list(acts)
    seeds=((obs.get('private',{}) or {}).get('seeds',{}) or {})
    for idx,base_act in enumerate(acts):
        q=queues.get(idx,[])
        if q:
            exec_act=q.pop(0)
            if not _v2_is_pass(base_act): q.append(copy.deepcopy(base_act))
            newacts[idx]=exec_act
            if q: queues[idx]=q
            else: queues.pop(idx,None)
            continue
        op=base_act[0] if isinstance(base_act,list) and base_act else None
        if idx>=len(positions): continue
        tile=_v2_tile(obs,player,positions[idx])
        if isinstance(tile,dict) and tile.get('kind')=='WEED':
            if op in ('BUILD_PASTURE','BUILD_COOP'):
                newacts[idx]=['DIG']; queues[idx]=[copy.deepcopy(base_act)]
            elif op=='PLANT' and len(base_act)>=2 and int(seeds.get(base_act[1],0) or 0)>0:
                newacts[idx]=['DIG']; queues[idx]=[copy.deepcopy(base_act)]
    out['farmer']=newacts[0] if newacts else ['PASS']; out['hands']=newacts[1:]
    return out

