# === q30 v3.2: throttled adaptive monetization ===
_Q30_THROTTLE={0:{},1:{}}
def _q30_extra_ok(p,item,s,cool=4):
    last=_Q30_THROTTLE.setdefault(p,{}).get(item,-999)
    return s-last>=cool
def _q30_extra_mark(p,item,s): _Q30_THROTTLE.setdefault(p,{})[item]=s

def q30_v3t(observation,configuration=None):
    a=copy.deepcopy(generic_q30_v1(observation,configuration))
    try:
        o=observation if isinstance(observation,dict) else {}; s=_q30_step(o); p=int(o.get('player',0) or 0)
        if s==0:_Q30_THROTTLE[p]={}
        if s<240:return a
        fs=o.get('farms',[]) or []; mode=_Q30V1_STATE.get(p,{}).get('mode')
        if len(fs)>=2 and mode=='LOW' and _q30_prod_distance(fs[p],fs[1-p])<=3:return a
        opp=fs[1-p]; shed=((o.get('private',{}) or {}).get('shed',{}) or {}); prices=((o.get('market',{}) or {}).get('prices',{}) or {}); shops=list(((o.get('town',{}) or {}).get('unlocked_shops',[]) or [])); m=list(a.get('market',[]) or [])
        dairy=any(x in ('SMOOTHIE_SHOP','PIZZA_SHOP','ICE_CREAM_SHOP') for x in shops); berry=any(x in ('SMOOTHIE_SHOP','BRUNCH_SPOT','ICE_CREAM_SHOP','FARMERS_MARKET') for x in shops); yarn='YARN_STORE' in shops; carrot=('PET_CAFE' in shops or 'FARMERS_MARKET' in shops)
        def add(item,q,cool=4):
            nonlocal m
            if q<=0 or not _q30_extra_ok(p,item,s,cool) or _q30_has_sale(m,item):return
            before=len(m); m=_q30_add_sale(m,item,q)
            if len(m)>before:_q30_extra_mark(p,item,s)
        if dairy and int(shed.get('MILK',0) or 0)>=4 and float(prices.get('MILK',0) or 0)>=80:add('MILK',min(4,int(shed.get('MILK',0) or 0)))
        if (s%4)==1:
            if yarn and int(shed.get('WOOL',0) or 0)>=2 and (float(prices.get('WOOL',0) or 0)>=150 or sum(int(v or 0) for v in shed.values())>=85):add('WOOL',min(3,int(shed.get('WOOL',0) or 0)))
            if berry and int(shed.get('STRAWBERRY',0) or 0)>=3 and float(prices.get('STRAWBERRY',0) or 0)>=85:add('STRAWBERRY',min(3,int(shed.get('STRAWBERRY',0) or 0)))
            if carrot and int(shed.get('CARROT',0) or 0)>=2 and float(prices.get('CARROT',0) or 0)>=30:add('CARROT',min(3,int(shed.get('CARROT',0) or 0)))
        st,mel=_q30_maturing(opp,int(o.get('day',0) or 0))
        if st>=4 and int(shed.get('STRAWBERRY',0) or 0)>=3 and float(prices.get('STRAWBERRY',0) or 0)>=100:add('STRAWBERRY',min(4,int(shed.get('STRAWBERRY',0) or 0)))
        if mel>=2 and int(shed.get('MELON',0) or 0)>=2 and float(prices.get('MELON',0) or 0)>=120:add('MELON',min(4,int(shed.get('MELON',0) or 0)))
        a['market']=_q30_merge_sell(m)[:10]
    except Exception:pass
    return a
agent=q30_v3t

# === q30 v3.3 regime-selective market controller ===
def _q30_herd(f):
    c=s=0
    for row in (f.get('tiles',[]) or []):
        for t in (row or []):
            if isinstance(t,dict):
                c += t.get('animal')=='COW'; s += t.get('animal')=='SHEEP'
    return c+s

def q30_v3h(observation,configuration=None):
    o=observation if isinstance(observation,dict) else {}
    try:
        p=int(o.get('player',0) or 0); s=_q30_step(o); fs=o.get('farms',[]) or []
        if len(fs)>=2 and s>=240:
            mode=_Q30V1_STATE.get(p,{}).get('mode')
            d=_q30_prod_distance(fs[p],fs[1-p])
            # Low-response near mirrors: preserve expert market schedule.
            if mode=='LOW' and d<=3:
                return generic_q30_v1(observation,configuration)
            # Public high-capacity / diverged opponent: keep aggressive v2a front-run.
            if _q30_herd(fs[1-p]) >= _q30_herd(fs[p])+2 or d>=8:
                return q30_v2a(observation,configuration)
    except Exception: pass
    # Similar-capacity non-LOW games use throttled capacity-aware execution.
    return q30_v3t(observation,configuration)
agent=q30_v3h


