_V3M_TAIL = _V3M_TYPES.ModuleType('_v3m_tail')
exec(compile(_V3M_TAIL_SRC, '<_v3m_tail>', 'exec'), _V3M_TAIL.__dict__)
_V3M_MODE={0:'BASE',1:'BASE'}
_V3M_DUE={0:{},1:{}}

def _v3m_step(o):
    return int(o.get('step', int(o.get('day',0) or 0)*24 + int(o.get('hour',0) or 0)) or 0)

def _v3m_repay(m,due):
    out=[]; rem=dict(due or {})
    for o in m:
        if isinstance(o,list) and len(o)>=3 and o[0]=='SELL' and rem.get(o[1],0)>0:
            q=int(o[2]); cut=min(q,rem[o[1]]); q-=cut; rem[o[1]]-=cut
            if q>0: out.append(['SELL',o[1],q])
        else: out.append(o)
    return out

def _v3m_tail_action(obs):
    s=_v3m_step(obs); p=int(obs.get('player',0) or 0)
    a=copy.deepcopy(_V3M_TAIL.agent(obs)); m=list(a.get('market',[]) or [])
    m=_v3m_repay(m,_V3M_DUE[p].pop(s,{}))
    try:
        A=getattr(_V3M_TAIL,'_A',None); r=A.R[A.cur]
        if s+1<len(r) and len(m)<10:
            nxt={}
            for o in (r[s+1].get('market') or []):
                if isinstance(o,list) and len(o)>=3 and o[0]=='SELL':
                    nxt[o[1]]=nxt.get(o[1],0)+int(o[2])
            shed=dict(((obs.get('private',{}) or {}).get('shed',{}) or {})); cur={}
            for o in m:
                if isinstance(o,list) and len(o)>=3 and o[0]=='SELL':
                    cur[o[1]]=cur.get(o[1],0)+int(o[2])
            prices=((obs.get('market',{}) or {}).get('prices',{}) or {}); cand=[]
            for it,q in nxt.items():
                avail=max(0,int(shed.get(it,0) or 0)-cur.get(it,0)); take=min(2,q,avail)
                if take>0 and float(prices.get(it,0) or 0)>1:
                    cand.append((float(prices.get(it,0) or 0)*take,it,take))
            if cand:
                _,it,take=max(cand); m.append(['SELL',it,take])
                d=_V3M_DUE[p].setdefault(s+1,{}); d[it]=d.get(it,0)+take
    except Exception:
        pass
    a['market']=m[:10]
    # Submission-safety shape guard: the embedded continuation can retain
    # speculative actions for hands that were not successfully hired. Those
    # actions are no-ops in the exact simulator; align to the public live hand
    # count without changing any executable hand action.
    try:
        fs=obs.get('farms',[]) or []
        farm=fs[p] if 0 <= p < len(fs) else {}
        nh=len(farm.get('hands',[]) or [])
        hs=list(a.get('hands',[]) or [])
        if len(hs)<nh: hs += [['PASS'] for _ in range(nh-len(hs))]
        a['hands']=hs[:nh]
    except Exception:
        pass
    return a

def q30_v3m(observation,configuration=None):
    o=observation if isinstance(observation,dict) else {}
    s=_v3m_step(o); p=int(o.get('player',0) or 0)
    if s==0:
        _V3M_MODE[p]='BASE'; _V3M_DUE[p]={}
        try: _V3M_TAIL._A=None
        except Exception: pass
    if s==72:
        fs=o.get('farms',[]) or []; opp=fs[1-p] if len(fs)>=2 else {}
        shops=list(((o.get('town',{}) or {}).get('unlocked_shops',[]) or []))
        opp_money=float(opp.get('money',9999) or 0)
        _V3M_MODE[p]='HIGHCAP' if (opp_money<=180 and (not shops or shops[0]!='YARN_STORE')) else 'BASE'
    if _V3M_MODE.get(p)=='HIGHCAP' and s>=72:
        return _v3m_tail_action(o)
    return _V3M_BASE_AGENT(o,configuration)

agent=q30_v3m


# === q30 v4b: liquidity-aware day-boundary reserve planner ===
_V4B_BASE = agent
_V4B_SEED_COST={'WHEAT':10,'CARROT':20,'TOMATO':50,'STRAWBERRY':100,'MELON':80}
def _v4b_orig_key(step,sh):
    if step<72:return 'OPENING',step
    if step<144:return 'S1_'+_cat(sh[0] if sh else ''),step-72
    if step<216:return 'S2_'+_s2(sh),step-144
    ph=min(9,step//72);return f'P{ph}_{_fam(sh)}',step-ph*72

def _v4b_fib_hire_cost(n):
    a,b=1,1; total=0
    for _ in range(max(0,int(n))):
        total += a; a,b=b,a+b
    return total

def _v4b_nextday_reserve(o,p,s):
    # Only plan one bootstrap market action ahead; later same-day SELLs can fund
    # later hires, so reserving the first block avoids unnecessary hoarding.
    nd=(s//24+1)*24
    if nd>718:return 0
    sh=list(((o.get('town',{}) or {}).get('unlocked_shops',[]) or []))
    # Respect v3j2's only physical S1 reroute when it is active.
    rsh=sh
    if 72<=nd<144 and _V3J2_S1_OVERRIDE.get(p)=='BAL': rsh=['BAKERY']+list(sh[1:])
    k,i=_v4b_orig_key(nd,rsh)
    try: mk=list(PROGRAM[k][i].get('market',[]) or [])
    except Exception:return 0
    # At the day boundary, reserve only the initial bootstrap hires before the
    # first cash-generating SELL.  HIRE cost resets daily.
    n=0
    for x in mk:
        if not isinstance(x,list) or not x: continue
        if x[0]=='SELL': break
        if x[0]=='HIRE': n += 1
    return _v4b_fib_hire_cost(n)

def _v4b_guard(a,o,p,s,configuration=None):
    # HIGHCAP has its own validated capital choreography; do not alter it.
    if _V3M_MODE.get(p)!='BASE': return a
    hour=s%24
    if hour<12 or hour>=24:return a
    reserve=_v4b_nextday_reserve(o,p,s)
    if reserve<=0:return a
    m=list(a.get('market',[]) or [])
    # If this turn explicitly sells first, preserve the validated funded basket.
    if any(isinstance(x,list) and x and x[0]=='SELL' for x in m): return a
    fs=o.get('farms',[]) or []; f=fs[p] if 0<=p<len(fs) else {}
    cash=float(f.get('money',0) or 0)
    prices=((o.get('market',{}) or {}).get('prices',{}) or {})
    out=[]
    for x in m:
        if not (isinstance(x,list) and x):
            out.append(x); continue
        op=x[0]
        if op in ('BUY_SEED','BUY_PRODUCT') and len(x)>=3:
            item=x[1]
            try:q=max(0,int(x[2]))
            except:q=0
            if op=='BUY_SEED': unit=float(_V4B_SEED_COST.get(item,0) or 0)
            else: unit=float(prices.get(item,0) or 0)
            if unit>0 and q>0:
                maxq=max(0,int((cash-reserve)//unit))
                take=min(q,maxq)
                if take>0:
                    y=list(x);y[2]=take;out.append(y);cash-=take*unit
                continue
        out.append(x)
    a['market']=out[:10]
    return a

def q30_v4b(observation,configuration=None):
    o=observation if isinstance(observation,dict) else {}
    p=int(o.get('player',0) or 0); s=_v3m_step(o)
    a=copy.deepcopy(_V4B_BASE(o,configuration))
    try:return _v4b_guard(a,o,p,s,configuration)
    except Exception:return a
agent=q30_v4b


# === q30 v4e: liquidity planner + generic YARN_SECOND market option ===
_V4E_BASE=agent
_V4E_Y2={0:False,1:False}
def q30_v4e(observation,configuration=None):
    o=observation if isinstance(observation,dict) else {};p=int(o.get('player',0) or 0);s=_v3m_step(o)
    if s==0:_V4E_Y2[p]=False
    if s==144:
        sh=list(((o.get('town',{}) or {}).get('unlocked_shops',[]) or []))
        if _V3M_MODE.get(p)=='BASE' and len(sh)>=2 and sh[1]=='YARN_STORE' and sh[0]!='YARN_STORE':_V4E_Y2[p]=True
    if _V4E_Y2.get(p) and s>=240:
        a=copy.deepcopy(q30_v2a(o,configuration));fs=o.get('farms',[]) or [];nh=len(fs[p].get('hands',[]) or []) if 0<=p<len(fs) else 0
        h=list(a.get('hands',[]) or []);h=h[:nh]+[['PASS'] for _ in range(max(0,nh-len(h)))];a['hands']=h;return a
    return _V4E_BASE(o,configuration)
agent=q30_v4e


# === King-v4e RC3: sparse public-state marginal-capital overlays ===
_RC3_HITS={0:[],1:[]}
_RC3_ANIMAL_COST={'SHEEP':500,'COW':400,'GOOSE':300}
_RC3_SEED_COST={'WHEAT':10,'CARROT':20,'TOMATO':50,'STRAWBERRY':100,'MELON':80}

def _rc3_step(o):
    return int(o.get('step',int(o.get('day',0) or 0)*24+int(o.get('hour',0) or 0)) or 0)

def _rc3_future_pick_qty(o,p,s,item,h=24):
    sh=list(((o.get('town',{}) or {}).get('unlocked_shops',[]) or []))
    phase_end=min(719,((s//72)+1)*72); end=min(phase_end,s+1+h); n=0; places=0
    for t in range(s+1,end):
        k,i=_v4b_orig_key(t,sh)
        if k not in PROGRAM or not (0<=i<len(PROGRAM[k])): continue
        aa=PROGRAM[k][i]
        for x in [aa.get('farmer')]+list(aa.get('hands',[]) or []):
            if not (isinstance(x,list) and len(x)>1): continue
            if x[0]=='PICKUP' and x[1]==item:
                try:n+=int(x[2]) if len(x)>2 else 1
                except:n+=1
            elif x[0]=='PLACE' and x[1]==item: places+=1
    return min(n,places) if places else 0

def _rc3_hire_cost_from(farm,n):
    def fib(i):
        a,b=1,1
        for _ in range(i): a,b=b,a+b
        return a
    cur=int(farm.get('hires_today',0) or 0)
    return sum(fib(cur+j) for j in range(n))

def _rc3_step241_sheep(a,o,p,s):
    # The old v5l allocator was too permissive late in the horizon.  RC3 allows
    # the exact same marginal-value test at one early compatible slot only.
    if s!=241 or _V3M_MODE.get(p)!='BASE': return a
    sh=list(((o.get('town',{}) or {}).get('unlocked_shops',[]) or []))
    if 'YARN_STORE' not in sh: return a
    m=list(a.get('market',[]) or []); idx=None; buyq=0
    for i,x in enumerate(m):
        if isinstance(x,list) and len(x)>=3 and x[0]=='BUY_ANIMAL' and x[1]=='SHEEP':
            idx=i
            try: buyq=max(0,int(x[2]))
            except: buyq=0
            break
    if idx is None: return a
    need=_rc3_future_pick_qty(o,p,s,'SHEEP',24)
    shed=int((((o.get('private',{}) or {}).get('shed',{}) or {}).get('SHEEP',0)) or 0)
    extra=min(1,max(0,need-(shed+buyq)))
    if extra<=0:return a
    fs=o.get('farms',[]) or []; farm=fs[p] if 0<=p<len(fs) else {}; cash=float(farm.get('money',0) or 0)
    hires=sum(1 for x in m if isinstance(x,list) and x and x[0]=='HIRE')
    structural=_rc3_hire_cost_from(farm,hires)
    for x in m:
        if not (isinstance(x,list) and x):continue
        op=x[0]
        if op=='BUY_ANIMAL' and len(x)>=3:
            try:structural+=_RC3_ANIMAL_COST.get(x[1],0)*max(0,int(x[2]))
            except:pass
        elif op=='BUY_SEED' and len(x)>=3:
            try:structural+=_RC3_SEED_COST.get(x[1],0)*max(0,int(x[2]))
            except:pass
        elif op=='BUY_LAND':
            uq=len(farm.get('unlocked_quadrants',[]) or [])
            structural += {1:1000,2:2000,3:4000}.get(uq,0)
    if cash-structural < 500*extra+100:return a
    y=list(m[idx]);y[2]=buyq+extra;m[idx]=y;a['market']=m[:10]
    _RC3_HITS[p].append(('SHEEP241',s,buyq,buyq+extra))
    return a

def _rc3_opp_active(farm):
    if not isinstance(farm,dict):return False
    if float(farm.get('money',0) or 0)>0:return True
    if len(farm.get('hands',[]) or [])>0:return True
    for row in farm.get('tiles',[]) or []:
        for t in row or []:
            if isinstance(t,dict) and (t.get('kind')=='PLANT' or t.get('crop') or t.get('animal')):return True
    return False

def _rc3_step385_fertilizer(a,o,p,s):
    # Conservative D16H1 throttle: keep choreography, only release one unit of
    # low-marginal fertilizer capital when we already carry a material reserve.
    if s!=385 or _V3M_MODE.get(p)!='BASE':return a
    shed=int((((o.get('private',{}) or {}).get('shed',{}) or {}).get('FERTILIZER',0)) or 0)
    if shed<12:return a
    fs=o.get('farms',[]) or []
    opp=fs[1-p] if len(fs)>=2 else {}
    if not _rc3_opp_active(opp):return a
    m=list(a.get('market',[]) or []);out=[];changed=False
    for x in m:
        if (not changed and isinstance(x,list) and len(x)>=3 and x[0]=='BUY_PRODUCT' and x[1]=='FERTILIZER'):
            try:q=max(0,int(x[2]))
            except:q=0
            if q>0:
                changed=True
                if q>1:
                    y=list(x);y[2]=q-1;out.append(y)
                _RC3_HITS[p].append(('FERT385',s,q,max(0,q-1)))
                continue
        out.append(x)
    if changed:a['market']=out[:10]
    return a

def king_v4e_rc3(observation,configuration=None):
    o=observation if isinstance(observation,dict) else {};p=int(o.get('player',0) or 0);s=_rc3_step(o)
    if s==0:_RC3_HITS[p]=[]
    if s>=719:
        fs=o.get('farms',[]) or [];nh=len((fs[p].get('hands',[]) if 0<=p<len(fs) else []) or [])
        return {'farmer':['PASS'],'hands':[['PASS'] for _ in range(nh)],'market':[]}
    a=copy.deepcopy(q30_v4e(o,configuration))
    try:a=_rc3_step241_sheep(a,o,p,s)
    except Exception:pass
    try:a=_rc3_step385_fertilizer(a,o,p,s)
    except Exception:pass
    return a

agent=king_v4e_rc3

# === King-v4e RC4: Smart Farm Strategy Lab late-liquidity ordering overlay ===
# Public family fingerprint observed after step 1.  The branch is deliberately
# sparse: it never changes quantities or worker choreography, and only moves
# HIRE orders behind other same-turn market operations from D24H1 onward.
_RC4_SF_LOCK={0:False,1:False}
_RC4_HITS={0:[],1:[]}

def _rc4_is_smartfarm_family(o,p):
    try:
        farms=o.get('farms',[]) or []
        opp=farms[1-p]
        return (
            float(opp.get('money',0) or 0)==66.0
            and opp.get('farmer')==[4,3]
            and len(opp.get('hands',[]) or [])==5
            and list(opp.get('unlocked_quadrants',[]) or [])==['NW']
        )
    except Exception:
        return False

def _rc4_hire_last(a,o,p,s):
    if not _RC4_SF_LOCK.get(p,False) or s<577:
        return a
    m=list(a.get('market',[]) or [])
    if len(m)<2 or not any(isinstance(x,list) and x and x[0]=='HIRE' for x in m):
        return a
    indexed=list(enumerate(m))
    ordered=sorted(indexed,key=lambda z:(1 if isinstance(z[1],list) and z[1] and z[1][0]=='HIRE' else 0,z[0]))
    out=[x for _,x in ordered]
    if out!=m:
        a['market']=out[:10]
        _RC4_HITS[p].append(('SF_HIRE_LAST',s))
    return a

def king_v4e_rc4(observation,configuration=None):
    o=observation if isinstance(observation,dict) else {}
    p=int(o.get('player',0) or 0)
    s=_rc3_step(o)
    if s==0:
        _RC4_SF_LOCK[p]=False
        _RC4_HITS[p]=[]
    a=king_v4e_rc3(o,configuration)
    if s==2 and _rc4_is_smartfarm_family(o,p):
        _RC4_SF_LOCK[p]=True
    try:
        a=_rc4_hire_last(a,o,p,s)
    except Exception:
        pass
    return a

agent=king_v4e_rc4
